/** Wo ein Fall geprüft werden kann: nur im Browser, mit Minecraft (Mod) oder auf einem Paper-Server mit Plugin. */
export type TestPlace = 'planer' | 'spiel' | 'server';
export const PLACE_LABEL: Readonly<Record<TestPlace, string>> = { planer: 'Nur im Browser', spiel: 'Mit Minecraft (Mod oder Spiel)', server: 'Mit Paper-Server und Plugin' };
const PLACE_ORDER: readonly TestPlace[] = ['planer', 'spiel', 'server'];

export function placeOf(c: TestCase): TestPlace {
  const area = TEST_AREAS.find(a => a.cases.includes(c));
  const text = [c.title, ...c.steps, c.expect].join(' ');
  if (area?.kind === 'server' || /Paper|Server mit (dem )?Plugin|auf (dem|Philipps) Server|Plugin auf dem Server/.test(text) && !/ohne (Bauplaner-)?Plugin/.test(text)) return 'server';
  if (area?.kind === 'mod' || /im Spiel|Minecraft|\/bauplaner|WorldEdit|Litematica|Mod 0\.|REI/.test(text)) return 'spiel';
  return 'planer';
}

/** Ort für die Abnahme eines Pakets: der anspruchsvollste Ort seiner Fälle. */
export function packagePlace(pkg: string): TestPlace {
  const places = (ACCEPTANCE[pkg] ?? []).map(id => ALL_CASES.find(c => c.id === id)).filter((c): c is TestCase => !!c).map(placeOf);
  return PLACE_ORDER[Math.max(0, ...places.map(p => PLACE_ORDER.indexOf(p)))] ?? 'planer';
}

/** Roadmap-Pakete, deren Abnahme ein Testfall abdeckt (Anzeige auf #/testphase). */
export function packagesOf(caseId: string): string[] {
  return Object.entries(ACCEPTANCE).filter(([, cases]) => cases.includes(caseId)).map(([pkg]) => pkg);
}

export function areaOf(caseId: string): TestArea | undefined {
  return TEST_AREAS.find(a => a.cases.some(c => c.id === caseId));
}
